194	// client returns the cached control-plane client, creating it on first use.
195	func (s *semanticSearchV4Session) client() (*coreapi.Client, error) {
196		s.mu.Lock()
197		defer s.mu.Unlock()
198		if s.coreClient != nil {
199			return s.coreClient, nil
200		}
201		c, err := coreapi.New()
202		if err != nil {
203			return nil, err
204		}
205		s.coreClient = c
206		return c, nil
207	}
