209	// listFullIndex fetches (once) and caches the caller's full repo index, used
210	// for unfiltered searches and raw-ID filter matching.
211	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
212		s.mu.Lock()
213		defer s.mu.Unlock()
214		if s.fullIndex != nil {
215			return s.fullIndex, nil
216		}
217		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
218		defer cancel()
219		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
220		if err != nil {
221			return nil, err
222		}
223		s.fullIndex = index
224		return index, nil
225	}
