354	// rerankOf returns query-serve's cross-encoder relevance score, or 0 when the
355	// row was not reranked (its cell fell back). Rows without a score sort after
356	// reranked ones, matching the BFF's rerankOf.
357	func rerankOf(r search.Result) float64 {
358		if r.Meta.RerankScore != nil {
359			return *r.Meta.RerankScore
