package cli

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/search"
	"github.com/entireio/cli/internal/coreapi"
)

// semanticSearchV4CellTimeout bounds each per-cell v4 query (token exchange +
// the query-serve call), mirroring codeSearchCellTimeout.
const semanticSearchV4CellTimeout = 30 * time.Second

// semanticSearchControlPlaneTimeout bounds each control-plane discovery call
// (repo index / repo lookup) on the v4 path.
const semanticSearchControlPlaneTimeout = 10 * time.Second

// semanticSearcher performs one semantic search. The command layer builds one
// per invocation (newSemanticSearcher) and every entry point — the one-shot
// command, the TUI's initial fetch, interactive re-searches, and pagination —
// calls through it, so all of them share one discovery cache.
type semanticSearcher func(ctx context.Context, cfg search.Config) (*search.Response, error)

// newSemanticSearcher returns the semantic-search entry for this invocation: a
// v4 query-serve session (ENT-1055) that fans out across entire-api cells and
// caches control-plane discovery across calls.
func newSemanticSearcher(insecureHTTP bool) semanticSearcher {
	s := &semanticSearchV4Session{insecureHTTP: insecureHTTP}
	return s.search
}

// loginHintErr maps auth.ErrNotLoggedIn to the standard login hint; other
// errors pass through unchanged.
func loginHintErr(err error) error {
	if errors.Is(err, auth.ErrNotLoggedIn) {
		return errors.New("not authenticated. Run 'entire login' to authenticate")
	}
	return err
}

// semanticSearchV4Session holds per-invocation state for the v4 query-serve
// path. Control-plane discovery (the repo index, per-slug repo lookups, the
// cluster catalog) is stable for the life of one command, so it is resolved
// once and reused across TUI re-searches and pagination instead of paying
// several network round trips per keystroke-search. Identity tokens are NOT
// cached here — fanOutCells mints them per search (at most one per
// jurisdiction), which keeps expiry handling in the auth layer.
type semanticSearchV4Session struct {
	insecureHTTP bool

	mu         sync.Mutex
	coreClient *coreapi.Client
	clusters   *cachedClusterClient
	fullIndex  *coreapi.ListReposOutputBody        // unfiltered index, fetched at most once
	slugRepos  map[string][]coreapi.RepoIndexEntry // per-filter exact-match lookups
}

// search performs a v4 query-serve search across every cell that hosts the
// caller's in-scope repos, then merges the per-cell responses into one
// response. It is the semantic sibling of searchAllCells (code): resolve
// scope → group by hosting cell → one query-serve call per cell → tiered
// merge.
//
// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
// --all-repos (the more specific filter scopes the search):
//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
//     is queried with NO repo param, so query-serve returns everything the
//     caller's token authorizes there (matching the BFF and keeping the query
//     small for users with many repos).
//   - explicit repo filter(s) or the current-repo default → the slugs are
//     resolved via truncation-proof exact-match lookups and each cell is
//     scoped to the ULIDs it hosts.
//
// Completeness caveats (truncated index, failed regions) are returned as
// Response.Warnings for the caller to surface.
func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
	if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
		return nil, err //nolint:wrapcheck // user-facing validation message
	}

	coreClient, err := s.client()
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return nil, loginHintErr(err)
		}
		return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
	}

	slugs, allRepos := cfg.ScopeSlugs()
	var cells []cellGroup
	var skipped []string
	var warnings []string
	indexTruncated := false
	scoped := !allRepos
	if scoped {
		if len(slugs) == 0 {
			return nil, errors.New("semantic search: could not determine the repository to search")
		}
		entries, err := s.resolveScope(ctx, slugs)
		if err != nil {
			return nil, err
		}
		// Scoped requests pin the picked placement's ULID (repoIDs below),
		// which query-serve resolves from its all-accessible byID set.
		cells, skipped = groupReposByCell(entries)
	} else {
		index, err := s.listFullIndex(ctx)
		if err != nil {
			return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
		}
		if index.Truncated {
			// Debug, not Warn: the user-facing channel is the Warnings entry;
			// slog's default handler would print a Warn straight to stderr on
			// commands whose context carries no logger.
			logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
			warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
			indexTruncated = true
		}
		// Broad requests send no repo pins; query-serve narrows pin-less
		// scope by the same election routedRepoPlacement picks by (ENT-1776),
		// so one grouping serves both request shapes.
		cells, skipped = groupReposByCell(index.Repos)
	}
	skipped = reportableSkippedRepos(ctx, scoped, len(cells), skipped)
	if len(skipped) > 0 {
		warnings = append(warnings, fmt.Sprintf("skipped %d repo(s) with no searchable placement (missing or not ready): %s", len(skipped), strings.Join(skipped, ", ")))
	}
	// The BFF's scope-loss channels (search.ts): a truncated repo index means
	// broad coverage silently misses repos; an explicitly-filtered repo
	// skipped as not-ready narrows the promised scope. Unfiltered skips stay
	// silent — nothing advertised was narrowed.
	scopeNarrowed := scoped && len(skipped) > 0

	if len(cells) == 0 {
		resp := &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings, Counts: &search.TypeCounts{}}
		if indexTruncated {
			// Every facet count is a lower bound, not an exact zero — same
			// contract as the BFF's zero-routable-cells answer.
			resp.Truncated = true
			resp.CountsLowerBound = map[string]bool{
				facetRepos: true, facetCheckpoints: true, facetCommits: true, facetPRs: true, facetSessions: true,
			}
		}
		if indexTruncated || scopeNarrowed {
			resp.Partial = true
			resp.CoverageIncomplete = true
		}
		return resp, nil
	}
	resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)

	results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
		// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
		// repo param and let query-serve search everything the token
		// authorizes in that cell (avoids per-request repo-filter caps for
		// large accounts).
		var repoIDs []string
		if scoped {
			repoIDs = group.repoIDs
		}
		return search.CellV4(ctx, client, cfg, repoIDs)
	})
	if err != nil {
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return nil, loginHintErr(err)
		}
		return nil, fmt.Errorf("semantic search: %w", err)
	}

	resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
	if err != nil {
		return nil, err
	}
	resp.Warnings = append(warnings, resp.Warnings...)
	if indexTruncated {
		resp.Truncated = true
	}
	if indexTruncated || scopeNarrowed {
		resp.Partial = true
		resp.CoverageIncomplete = true
	}
	return resp, nil
}

// client returns the cached control-plane client, creating it on first use.
func (s *semanticSearchV4Session) client() (*coreapi.Client, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.coreClient != nil {
		return s.coreClient, nil
	}
	c, err := coreapi.New()
	if err != nil {
		return nil, err
	}
	s.coreClient = c
	return c, nil
}

// listFullIndex fetches (once) and caches the caller's full repo index, used
// for unfiltered searches and raw-ID filter matching.
func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.fullIndex != nil {
		return s.fullIndex, nil
	}
	reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
	defer cancel()
	index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
	if err != nil {
		return nil, err
	}
	s.fullIndex = index
	return index, nil
}

// resolveScope resolves explicit repo filters (or the current-repo default)
// to index entries, deduped by repo ID. owner/name slugs use the exact-match
// ListRepos filter — immune to index truncation on large accounts — while raw
// IDs (no slash) fall back to matching against the full index. Zero matches
// is a clear error; a partially matched multi-repo filter proceeds with the
// matches, like resolveRepoFilters does for code search.
func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
	var entries []coreapi.RepoIndexEntry
	seen := make(map[string]bool, len(slugs))
	for _, f := range slugs {
		matched, err := s.lookupFilter(ctx, f)
		if err != nil {
			return nil, err
		}
		for _, e := range matched {
			if !seen[e.ID] {
				seen[e.ID] = true
				entries = append(entries, e)
			}
		}
	}
	if len(entries) == 0 {
		return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
	}
	return entries, nil
}

// lookupFilter resolves one repo filter to index entries, cached per session.
// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
// matches full_name (case-insensitive, server-side exact match), and a raw
// ULID matches the index entry's ID.
func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
	s.mu.Lock()
	if cached, ok := s.slugRepos[filter]; ok {
		s.mu.Unlock()
		return cached, nil
	}
	s.mu.Unlock()

	slug := strings.TrimPrefix(filter, "gh/")
	var matched []coreapi.RepoIndexEntry
	if strings.Contains(slug, "/") {
		lookupCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
		defer cancel()
		out, err := s.coreClient.ListRepos(lookupCtx, coreapi.ListReposParams{Filter: coreapi.NewOptString(slug)})
		if err != nil {
			return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
		}
		matched = out.Repos
	} else {
		// Raw repo ID — the exact-match filter only matches full_name, so
		// match by ID against the full index.
		index, err := s.listFullIndex(ctx)
		if err != nil {
			return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
		}
		_, matched = resolveRepoFilters([]string{filter}, index.Repos)
	}

	s.mu.Lock()
	if s.slugRepos == nil {
		s.slugRepos = make(map[string][]coreapi.RepoIndexEntry)
	}
	s.slugRepos[filter] = matched
	s.mu.Unlock()
	return matched, nil
}

// clusterClient returns a cellCoreClient whose ListClusters is memoized for
// the session, so re-searches don't refetch the (stable) cluster catalog.
func (s *semanticSearchV4Session) clusterClient(inner *coreapi.Client) cellCoreClient {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.clusters == nil {
		s.clusters = &cachedClusterClient{inner: inner}
	}
	return s.clusters
}

// cachedClusterClient is a cellCoreClient that caches a successful
// ListClusters result; failures are not cached, so the next call retries.
// The other methods delegate unchanged.
type cachedClusterClient struct {
	inner cellCoreClient

	mu       sync.Mutex
	clusters *coreapi.ListClustersOutputBody
}

func (c *cachedClusterClient) ListClusters(ctx context.Context) (*coreapi.ListClustersOutputBody, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.clusters != nil {
		return c.clusters, nil
	}
	out, err := c.inner.ListClusters(ctx)
	if err != nil {
		return nil, err //nolint:wrapcheck // transparent delegation
	}
	c.clusters = out
	return out, nil
}

func (c *cachedClusterClient) GetRepo(ctx context.Context, params coreapi.GetRepoParams) (*coreapi.Repo, error) {
	return c.inner.GetRepo(ctx, params) //nolint:wrapcheck // transparent delegation
}

func (c *cachedClusterClient) ListRepos(ctx context.Context, params coreapi.ListReposParams) (*coreapi.ListReposOutputBody, error) {
	return c.inner.ListRepos(ctx, params) //nolint:wrapcheck // transparent delegation
}

// tierOf returns a result's tier, or -1 when unset (dropped by the merge,
// like every tier outside 0/1 — see rankSemanticResults).
func tierOf(r search.Result) int {
	if r.Meta.Tier == nil {
		return -1
	}
	return *r.Meta.Tier
}

func bm25Of(r search.Result) float64 {
	if r.Meta.BM25Score != nil {
		return *r.Meta.BM25Score
	}
	return 0
}

// rerankOf returns query-serve's cross-encoder relevance score, or 0 when the
// row was not reranked (its cell fell back). Rows without a score sort after
// reranked ones, matching the BFF's rerankOf.
func rerankOf(r search.Result) float64 {
	if r.Meta.RerankScore != nil {
		return *r.Meta.RerankScore
	}
	return 0
}

// semanticCellPage is one cell's successful response.
type semanticCellPage struct {
	body *search.Response
}

// classifySemanticCells splits per-cell outcomes into successful pages, hard
// failures, and quietly-skipped cells. A cell is skipped — not failed — when
// it can't serve the search yet: its gateway has no query-serve route, or the
// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
// mid-onboarding). Neither is worth warning the user about on every search.
func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
	var skipped, unmatched []string
	var unmatchedErr error
	for _, r := range results {
		switch {
		case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
			skipped = append(skipped, r.group.label())
		case errors.Is(r.err, search.ErrRepoFilterUnmatched):
			// The cell answered; the repo filter just matched nothing there.
			// Quiet like a skip when another cell has results, but if NO cell
			// matches it must surface as a repo problem, never a region one.
			unmatched = append(unmatched, r.group.label())
			unmatchedErr = r.err
		case r.err != nil:
			lastErr = r.err
			failed = append(failed, r.group.label())
		case r.value != nil:
			pages = append(pages, semanticCellPage{body: r.value})
		}
	}
	if len(skipped) > 0 {
		logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
	}
	if len(unmatched) > 0 {
		// unmatchedErr carries the server's own message (CellV4 wraps it into
		// the sentinel) — keep it visible here for diagnosis.
		logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
	}
	if len(pages) == 0 && lastErr == nil {
		switch {
		case len(unmatched) > 0:
			// Takes priority over the region message: a cell answering proves
			// its region serves semantic search.
			lastErr = errNoRepoAvailable
		case len(skipped) > 0:
			lastErr = errNoRegionAvailable
		}
	}
	return pages, failed, lastErr
}

// errNoRepoAvailable is returned when at least one cell answered but none
// matched the repo filter. A typo'd name or missing access cannot reach this
// point — resolveScope already validated the slug against the control-plane
// repo index — so the message names only the causes that survive: query-serve
// hasn't indexed the repo, or its owner org isn't enabled for semantic search.
var errNoRepoAvailable = errors.New("semantic search cannot search this repo yet — it may not be indexed, or semantic search may not be enabled for its owner")

// errNoRegionAvailable is returned when every queried cell lacks query-serve.
var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")

// tier0Row pairs a tier-0 result with its rank within the cell that returned
// it — the selection order the mixed-capability fallback preserves (see
// sortTier0Rows).
type tier0Row struct {
	r        search.Result
	cellRank int
}

// rankSemanticResults buckets every page's rows and applies the SAME ordering
// the BFF's cross-cell merge uses (see the ordering contract on
// mergeSemanticV4Responses): repos first by retrieval score desc, then tier 0
// (sortTier0Rows), then tier 1 by rerank desc with retrieval Score tiebreak.
// Every other non-repo row — tier 2 (the retired ANN-only fallback, still
// emitted by un-redeployed cells) and rows with no tier at all — is DROPPED,
// exactly as the BFF drops them. Ordering by rerank score — not BM25 or the
// per-namespace retrieval Score — is what keeps the CLI in parity with the
// web: query-serve documents that Score "is not the field results are ordered
// by … sorting by it undoes reranking."
func rankSemanticResults(pages []semanticCellPage) (merged []search.Result) {
	var repos, tier1 []search.Result
	var tier0 []tier0Row
	for _, p := range pages {
		cellRank := 0
		for _, r := range p.body.Results {
			switch {
			case r.Type == search.TypeRepo:
				repos = append(repos, r)
			case tierOf(r) == 0:
				tier0 = append(tier0, tier0Row{r: r, cellRank: cellRank})
				cellRank++
			case tierOf(r) == 1:
				tier1 = append(tier1, r)
			}
		}
	}
	sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
	merged = append(merged, repos...)
	sortTier0Rows(tier0)
	// Tier 1: rerank score decides, retrieval Score breaks ties. Rows whose
	// cell fell back (no rerank score) sort last, matching the BFF.
	sort.SliceStable(tier1, func(i, j int) bool {
		if ri, rj := rerankOf(tier1[i]), rerankOf(tier1[j]); ri != rj {
			return ri > rj
		}
		return tier1[i].Meta.Score > tier1[j].Meta.Score
	})
	for _, t := range tier0 {
		merged = append(merged, t.r)
	}
	merged = append(merged, tier1...)
	return merged
}

// sortTier0Rows orders the tier-0 band the way the BFF's sortTier0 does
// (ENT-1431). When EVERY row was judged by the cross-encoder, rerank score
// decides and BM25 breaks ties. When any row is missing a rerank score — its
// cell predates tier-0 reranking — a global rerank sort would demote all of
// that cell's full-phrase hits regardless of relevance, so instead the rows are
// interleaved positionally (each cell's #1, then each cell's #2, …), preserving
// every cell's own selection order, with BM25 breaking ties between same-rank
// rows. Converges to rerank-first once every cell is current.
func sortTier0Rows(tier0 []tier0Row) {
	allScored := true
	for _, t := range tier0 {
		if t.r.Meta.RerankScore == nil {
			allScored = false
			break
		}
	}
	if allScored {
		sort.SliceStable(tier0, func(i, j int) bool {
			if ri, rj := rerankOf(tier0[i].r), rerankOf(tier0[j].r); ri != rj {
				return ri > rj
			}
			return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
		})
		return
	}
	sort.SliceStable(tier0, func(i, j int) bool {
		if tier0[i].cellRank != tier0[j].cellRank {
			return tier0[i].cellRank < tier0[j].cellRank
		}
		return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
	})
}

// dedupSemanticResults removes cross-cell duplicate SESSION rows, keeping the
// first (higher-ranked) copy — the BFF's exact rule: sessions are the one type
// that legitimately repeats across cells (a crosslinked session attached to
// repos homed in different cells), while repo-bound types are canonical to one
// cell since the fan-out routes each repo to its single home placement
// (ENT-1672/ENT-1776). The key is the global session id when present, else the
// repo-qualified carrier checkpoint (server-folded legacy rows, ENT-1595);
// rows with neither are always kept.
func dedupSemanticResults(merged []search.Result) []search.Result {
	seen := make(map[string]bool)
	deduped := merged[:0]
	for _, r := range merged {
		if r.Type != search.TypeSession {
			deduped = append(deduped, r)
			continue
		}
		id := r.DedupID()
		if id == "" {
			deduped = append(deduped, r)
			continue
		}
		key := r.Type + "\x00" + id
		if seen[key] {
			continue
		}
		seen[key] = true
		deduped = append(deduped, r)
	}
	return deduped
}

// Facet names for the wire maps (truncated_types / counts_lower_bound) — the
// BFF's RESULT_TYPE_TO_FACET values.
const (
	facetRepos       = "repos"
	facetCheckpoints = "checkpoints"
	facetCommits     = "commits"
	facetPRs         = "prs"
	facetSessions    = "sessions"
)

// semanticFacetOf maps a wire result type to its counts/truncation facet name
// (the BFF's RESULT_TYPE_TO_FACET). Unknown types have no facet: they are kept
// in results, exempt from the per-type cap, and counted only in the total.
func semanticFacetOf(typ string) (string, bool) {
	switch typ {
	case search.TypeRepo:
		return facetRepos, true
	case search.TypeCheckpoint:
		return facetCheckpoints, true
	case search.TypeCommit:
		return facetCommits, true
	case search.TypePR:
		return facetPRs, true
	case search.TypeSession:
		return facetSessions, true
	}
	return "", false
}

// capSemanticPerType applies the BFF's per-type window: walk the merged list
// in order and keep at most `limit` rows of each facet, recording which facets
// overflowed. Rows without a facet mapping are kept uncounted.
func capSemanticPerType(merged []search.Result, limit int) ([]search.Result, map[string]bool) {
	truncated := make(map[string]bool)
	if limit <= 0 {
		return merged, truncated
	}
	perFacet := make(map[string]int, 5)
	out := merged[:0]
	for _, r := range merged {
		facet, ok := semanticFacetOf(r.Type)
		if !ok {
			out = append(out, r)
			continue
		}
		perFacet[facet]++
		if perFacet[facet] > limit {
			truncated[facet] = true
			continue
		}
		out = append(out, r)
	}
	return out, truncated
}

// deriveSemanticCounts computes total and per-type counts from the FINAL
// merged list — the BFF's per-type contract (ENT-1363): counts describe
// exactly what the caller can see, never the cells' corpus-count passes,
// with counts_lower_bound marking the facets whose lists were capped.
func deriveSemanticCounts(merged []search.Result) (int, *search.TypeCounts) {
	counts := &search.TypeCounts{}
	for _, r := range merged {
		switch r.Type {
		case search.TypeRepo:
			counts.Repos++
		case search.TypeCheckpoint:
			counts.Checkpoints++
		case search.TypeCommit:
			counts.Commits++
		case search.TypePR:
			counts.PRs++
		case search.TypeSession:
			counts.Sessions++
		}
	}
	return len(merged), counts
}

// mergeSemanticV4Responses interleaves per-cell query-serve responses into
// one final page. THE CROSS-CELL MERGE ORDERING CONTRACT lives here and in
// the BFF's mergeCellResponses (entire.io api/src/routes/search.ts) — the two
// implementations must stay byte-identical (ENT-1777); change one, change
// both, and update this block:
//
//  1. Band order: repo rows first (retrieval score desc), then tier 0, then
//     tier 1. Tier 2 and tier-less non-repo rows are dropped — the ANN-only
//     fallback tier is retired and only un-redeployed cells still emit it.
//     Band order deliberately overrides each cell's own post-fold final
//     order (entire-search#181 folds after ranking): the clients match each
//     other, not the leaf.
//  2. Tier 0: when every row carries a rerank score, rerank desc with BM25
//     tiebreak; when any cell predates tier-0 reranking, positional
//     interleave by in-cell rank with BM25 tiebreak (sortTier0Rows). Tier 1:
//     rerank desc, retrieval Score tiebreak. All sorts are STABLE — equal
//     keys keep cell-response order.
//  3. Dedupe AFTER ordering, BEFORE the per-type cap, sessions only, first
//     (highest-ranked) copy wins (dedupSemanticResults).
//  4. Per-type window: at most `limit` rows of each facet, overflow recorded
//     in truncated_types, unioned with the cells' own truncated_types
//     (capSemanticPerType). No global cut.
//  5. Counts and total derive from the FINAL list (deriveSemanticCounts);
//     counts_lower_bound == the capped facets.
//  6. Flags: truncated = any cell truncated; partial = truncated ∨ any cell
//     failed ∨ any cell partial ∨ mixed rerank capability; coverage_incomplete
//     = the same minus rerank-mix; reranked = every cell reranked (emitted
//     when any cell reported the field).
//
// Rerank scores share a space across cells (same Cohere model), so
// interleaving is meaningful. All-cells-failed is an error; a partial failure
// is noted in Warnings (and the flags) and the surviving cells are merged.
func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
	pages, failed, lastErr := classifySemanticCells(ctx, results)
	if len(pages) == 0 {
		if lastErr != nil {
			return nil, fmt.Errorf("semantic search: %w", lastErr)
		}
		return &search.Response{Results: []search.Result{}, Page: 1}, nil
	}
	var warnings []string
	if len(failed) > 0 {
		// Debug, not Warn: the warning below already reaches the user via
		// Response.Warnings, and slog's default handler would print a Warn
		// straight to stderr on commands whose context carries no logger.
		logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
			"succeeded", len(pages), "total", len(results), "failed_cells", failed)
		warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
	}

	merged := rankSemanticResults(pages)
	merged = dedupSemanticResults(merged)
	merged, truncatedTypes := capSemanticPerType(merged, limit)
	for _, p := range pages {
		for facet, v := range p.body.TruncatedTypes {
			if v {
				truncatedTypes[facet] = true
			}
		}
	}
	if merged == nil {
		merged = []search.Result{}
	}

	total, counts := deriveSemanticCounts(merged)
	resp := &search.Response{
		Results:  merged,
		Total:    total,
		Page:     max(page, 1),
		Counts:   counts,
		Warnings: warnings,
	}
	if len(truncatedTypes) > 0 {
		resp.TruncatedTypes = truncatedTypes
		resp.CountsLowerBound = make(map[string]bool, len(truncatedTypes))
		for facet := range truncatedTypes {
			resp.CountsLowerBound[facet] = true
		}
	}

	anyRerankedField, anyReranked, allReranked := false, false, true
	for _, p := range pages {
		if p.body.Truncated {
			resp.Truncated = true
		}
		if p.body.Partial {
			resp.Partial = true
			resp.CoverageIncomplete = true
		}
		if p.body.Reranked != nil {
			anyRerankedField = true
			if *p.body.Reranked {
				anyReranked = true
			} else {
				allReranked = false
			}
		} else {
			allReranked = false
		}
	}
	if len(failed) > 0 || resp.Truncated {
		resp.Partial = true
		resp.CoverageIncomplete = true
	}
	if anyReranked && !allReranked {
		// Mixed rerank capability skews ordering but not coverage — partial
		// without coverage_incomplete, matching the BFF.
		resp.Partial = true
	}
	if anyRerankedField {
		resp.Reranked = &allReranked
	}
	return resp, nil
}

package search

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"time"

	ulid "github.com/oklog/ulid/v2"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

const apiTimeout = 30 * time.Second

// v4ServicePath is the per-repo v4 query-serve route exposed by the entire-api
// cell gateway. It takes repo=<ULID>. The BFF (entire.io /api/v1/search)
// forwards to this same path; the CLI dials the cell directly with a
// jurisdictional identity token, skipping the BFF hop.
const v4ServicePath = "/api/v1/semantic-search/search/v1/search"

// ErrCellUnavailable reports that a cell's gateway does not expose the
// semantic-search route at all (HTTP 404 at the route level) — query-serve is
// not deployed in that cell yet. Callers fanning out across cells match it
// with errors.Is and skip the cell quietly instead of warning the user about
// a "failed" region.
var ErrCellUnavailable = errors.New("semantic search is not available in this cell")

// ErrRepoFilterUnmatched reports that query-serve answered (the route exists)
// but the explicit repo filter matched nothing the caller can search — the
// repo isn't indexed yet, or its owner org isn't enabled on the
// semantic-search feature flag (entire-search fails closed with a JSON 404,
// existence not disclosed). A typo'd repo can't produce this from the CLI:
// the slug was already resolved against the control-plane index before any
// cell was contacted. Distinct from ErrCellUnavailable so fan-out callers
// don't misreport a repo-level miss as a region without query-serve.
var ErrRepoFilterUnmatched = errors.New("no requested repo was found in this cell")

// WildcardQuery is the query string used when only filters are provided (no search terms).
const WildcardQuery = "*"

// AllReposFilter is the inline repo filter value that disables repo scoping.
const AllReposFilter = "*"

// Result type constants.
const (
	TypeCheckpoint = "checkpoint"
	TypeCommit     = "commit"
	TypeSession    = "session"
	// TypeRepo and TypePR are returned by the backend but have no typed struct
	// (decoded via rawData). They're named so the cross-cell v4 merge can bucket
	// and tally them without string literals.
	TypeRepo = "repo"
	TypePR   = "pr"
)

// DefaultLimit is the default number of results to fetch per request, matching the UI.
const DefaultLimit = 100

// Meta contains search ranking metadata for a result.
type Meta struct {
	MatchType string  `json:"matchType"`
	Score     float64 `json:"score"`
	Tier      *int    `json:"tier,omitempty"`
	Snippet   string  `json:"snippet,omitempty"`
	Summary   string  `json:"summary,omitempty"`
	// RerankScore is query-serve's cross-encoder (Cohere) relevance judgement,
	// present only on results that went through reranking. Where present it is
	// the signal the final ordering was built from and the only score
	// comparable across repos — Score is per-namespace retrieval strength, so
	// sorting by it undoes reranking. The cross-cell merge orders tier 0 and
	// tier 1 by this field, matching the BFF (ENT-1425/ENT-1431).
	RerankScore *float64 `json:"rerankScore,omitempty"`
	BM25Score   *float64 `json:"bm25Score,omitempty"`
	ANNScore    *float64 `json:"annScore,omitempty"`
}

// CheckpointResult represents a checkpoint returned by the search service.
type CheckpointResult struct {
	ID             string   `json:"id"`
	Prompt         string   `json:"prompt"`
	CommitMessage  *string  `json:"commitMessage"`
	CommitSubject  *string  `json:"commitSubject"`
	CommitSHA      *string  `json:"commitSha"`
	Branch         string   `json:"branch"`
	Org            string   `json:"org"`
	Repo           string   `json:"repo"`
	Author         string   `json:"author"`
	AuthorUsername *string  `json:"authorUsername"`
	CreatedAt      string   `json:"createdAt"`
	FilesTouched   []string `json:"filesTouched"`
}

// CommitResult represents a commit returned by the search service.
type CommitResult struct {
	ID             string  `json:"id"`
	CommitSHA      string  `json:"commitSha"`
	CommitMessage  string  `json:"commitMessage"`
	CommitSubject  string  `json:"commitSubject"`
	Branch         string  `json:"branch"`
	Org            string  `json:"org"`
	Repo           string  `json:"repo"`
	Author         string  `json:"author"`
	AuthorUsername *string `json:"authorUsername"`
	CreatedAt      string  `json:"createdAt"`
	Additions      int     `json:"additions"`
	Deletions      int     `json:"deletions"`
	FilesChanged   int     `json:"filesChanged"`
	HTMLUrl        *string `json:"htmlUrl"`
}

// SessionResult represents a session returned by the search service.
type SessionResult struct {
	SessionID string `json:"sessionId"`
	// MatchedCheckpointID is the carrier checkpoint the search service anchors a
	// session row to — present on every session row. For a server-folded legacy
	// session (ENT-1595) the sessionId is empty and this IS the row's identity
	// (the checkpoint predates the sessionId attribute), so ResultID and the
	// cross-cell dedupe (DedupID) fall back to it, repo-qualified, and a mirrored
	// repo reports the row once instead of twice. Drill-down is
	// `entire checkpoint explain <id>`, not `entire session info`.
	MatchedCheckpointID string  `json:"matchedCheckpointId,omitempty"`
	DisplayName         string  `json:"displayName"`
	Prompt              *string `json:"prompt"`
	Agent               *string `json:"agent"`
	Model               *string `json:"model"`
	StepCount           int     `json:"stepCount"`
	Org                 string  `json:"org"`
	Repo                string  `json:"repo"`
	Branch              *string `json:"branch"`
	AuthorUsername      *string `json:"authorUsername"`
	CreatedAt           string  `json:"createdAt"`
}

// Result wraps a search result with its type and ranking metadata.
// Exactly one of Checkpoint, Commit, or Session is non-nil based on Type.
type Result struct {
	Type       string            `json:"-"`
	Meta       Meta              `json:"-"`
	Checkpoint *CheckpointResult `json:"-"`
	Commit     *CommitResult     `json:"-"`
	Session    *SessionResult    `json:"-"`

	// rawData preserves the original JSON for unknown types (repo, pr).
	rawData json.RawMessage
	// rawFields is rawData decoded once at unmarshal time, and only for types
	// without a typed struct (repo, pr) — accessors never read raw fields for
	// typed rows, so a backend field addition cannot change what they return.
	rawFields map[string]json.RawMessage
}

// resultJSON is the wire format for JSON marshaling/unmarshaling.
type resultJSON struct {
	Type string          `json:"type"`
	Data json.RawMessage `json:"data"`
	Meta Meta            `json:"searchMeta"`
}

// MarshalJSON implements custom JSON marshaling to produce the API wire format.
func (r *Result) MarshalJSON() ([]byte, error) {
	var data any
	switch r.Type {
	case TypeCheckpoint:
		data = r.Checkpoint
	case TypeCommit:
		data = r.Commit
	case TypeSession:
		data = r.Session
	default:
		data = r.rawData
	}
	raw, err := json.Marshal(data)
	if err != nil {
		return nil, fmt.Errorf("marshaling result data: %w", err)
	}
	out, err := json.Marshal(resultJSON{
		Type: r.Type,
		Data: raw,
		Meta: r.Meta,
	})
	if err != nil {
		return nil, fmt.Errorf("marshaling result: %w", err)
	}
	return out, nil
}

// UnmarshalJSON implements custom JSON unmarshaling to parse typed data.
func (r *Result) UnmarshalJSON(b []byte) error {
	var raw resultJSON
	if err := json.Unmarshal(b, &raw); err != nil {
		return fmt.Errorf("unmarshaling result: %w", err)
	}
	r.Type = raw.Type
	r.Meta = raw.Meta
	r.rawData = raw.Data
	// Clear any previously-decoded payloads so a reused Result keeps the
	// "exactly one typed pointer is non-nil" invariant.
	r.Checkpoint, r.Commit, r.Session = nil, nil, nil
	r.rawFields = nil

	switch raw.Type {
	case TypeCheckpoint:
		var d CheckpointResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling checkpoint data: %w", err)
		}
		r.Checkpoint = &d
	case TypeCommit:
		var d CommitResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling commit data: %w", err)
		}
		r.Commit = &d
	case TypeSession:
		var d SessionResult
		if err := json.Unmarshal(raw.Data, &d); err != nil {
			return fmt.Errorf("unmarshaling session data: %w", err)
		}
		r.Session = &d
	default:
		// Unknown types (repo, pr): decode the payload once so accessors can
		// read identifying fields without re-parsing per call (the TUI calls
		// them per row per render).
		_ = json.Unmarshal(raw.Data, &r.rawFields) //nolint:errcheck // best-effort; accessors return "" when nil
	}
	return nil
}

// resultField dispatches to the accessor matching the result's type, guarding
// against a nil payload (returns "" for nil or unknown types like repo/pr).
func resultField(r *Result, fromCheckpoint func(*CheckpointResult) string, fromCommit func(*CommitResult) string, fromSession func(*SessionResult) string) string {
	switch r.Type {
	case TypeCheckpoint:
		if r.Checkpoint != nil {
			return fromCheckpoint(r.Checkpoint)
		}
	case TypeCommit:
		if r.Commit != nil {
			return fromCommit(r.Commit)
		}
	case TypeSession:
		if r.Session != nil {
			return fromSession(r.Session)
		}
	}
	return ""
}

// rawString returns the first non-empty string value among the given keys in
// the raw payload of a result without a typed struct (repo, pr). Returns ""
// for typed results — rawFields is only populated for unknown types — or when
// no key matches.
func (r *Result) rawString(keys ...string) string {
	for _, k := range keys {
		var s string
		if err := json.Unmarshal(r.rawFields[k], &s); err == nil && s != "" {
			return s
		}
	}
	return ""
}

// ResultOrg returns the org for any result type. Repo/PR raw payloads may
// only carry an owner-qualified "fullName"; its owner segment is the org.
func (r *Result) ResultOrg() string {
	if v := resultField(r,
		func(c *CheckpointResult) string { return c.Org },
		func(c *CommitResult) string { return c.Org },
		func(s *SessionResult) string { return s.Org }); v != "" {
		return v
	}
	if v := r.rawString("org"); v != "" {
		return v
	}
	owner, _ := splitFullName(r.rawString("fullName"))
	return owner
}

// ResultRepo returns the bare repo name (no owner) for any result type, so
// callers can join it with ResultOrg without doubling the owner. Repo/PR raw
// payloads carry it under "repo" or "name", or qualified inside "fullName".
func (r *Result) ResultRepo() string {
	if v := resultField(r,
		func(c *CheckpointResult) string { return c.Repo },
		func(c *CommitResult) string { return c.Repo },
		func(s *SessionResult) string { return s.Repo }); v != "" {
		return v
	}
	if v := r.rawString("repo", "name"); v != "" {
		return v
	}
	_, name := splitFullName(r.rawString("fullName"))
	return name
}

// splitFullName splits an "owner/repo" full name; without a slash the whole
// value is the repo name.
func splitFullName(fullName string) (owner, name string) {
	if i := strings.IndexByte(fullName, '/'); i >= 0 {
		return fullName[:i], fullName[i+1:]
	}
	return "", fullName
}

// ResultBranch returns the branch for any result type. PR raw payloads carry
// the head branch under "headBranch" (searcher.PRResult).
func (r *Result) ResultBranch() string {
	if v := resultField(r,
		func(c *CheckpointResult) string { return c.Branch },
		func(c *CommitResult) string { return c.Branch },
		func(s *SessionResult) string {
			if s.Branch != nil {
				return *s.Branch
			}
			return ""
		}); v != "" {
		return v
	}
	return r.rawString("headBranch")
}

// ResultCreatedAt returns the createdAt for any result type.
func (r *Result) ResultCreatedAt() string {
	if v := resultField(r,
		func(c *CheckpointResult) string { return c.CreatedAt },
		func(c *CommitResult) string { return c.CreatedAt },
		func(s *SessionResult) string { return s.CreatedAt }); v != "" {
		return v
	}
	return r.rawString("createdAt")
}

// ResultAuthor returns the display author for any result type. PR raw payloads
// carry the author login under "userLogin" (searcher.PRResult).
func (r *Result) ResultAuthor() string {
	if v := resultField(r,
		func(c *CheckpointResult) string {
			if c.AuthorUsername != nil && *c.AuthorUsername != "" {
				return *c.AuthorUsername
			}
			return c.Author
		},
		func(c *CommitResult) string {
			if c.AuthorUsername != nil && *c.AuthorUsername != "" {
				return *c.AuthorUsername
			}
			return c.Author
		},
		func(s *SessionResult) string {
			if s.AuthorUsername != nil {
				return *s.AuthorUsername
			}
			return ""
		}); v != "" {
		return v
	}
	return r.rawString("userLogin")
}

// ResultID returns the primary ID for any result type. Types without a typed
// struct (repo, pr) fall back to the "id" field of the raw payload, so a
// cross-cell merge can still identify the same logical result returned by two
// cells (e.g. a repo mirrored in both).
func (r *Result) ResultID() string {
	if id := resultField(r,
		func(c *CheckpointResult) string { return c.ID },
		func(c *CommitResult) string { return c.CommitSHA },
		func(s *SessionResult) string {
			if s.SessionID != "" {
				return s.SessionID
			}
			return s.MatchedCheckpointID // server-folded legacy session (ENT-1595)
		}); id != "" {
		return id
	}
	return r.rawString("id")
}

// DedupID is the identity used to collapse cross-cell duplicates. It matches
// ResultID except for the id types that can REPEAT across repos, which it
// repo-qualifies so two repos' rows sharing an id don't collide in the deduper
// and drop a valid result:
//   - a raw checkpoint id, and the checkpoint id a server-folded legacy session
//     (ENT-1595) falls back to — checkpoint ids are a mixed space (legacy 12-hex
//     ids repeat across repos; newer ULIDs are global), so qualifying by repo is
//     safe for both and necessary for the legacy half;
//   - a commit SHA — globally unique as a content address, but the SAME commit
//     legitimately lives in many repos (a fork and its upstream), so a bare SHA
//     would drop one repo's hit for every shared commit.
//
// Repo ULIDs and real session ids are globally unique, so they pass through.
// Mirrors of the SAME repo still carry the same org/repo and collapse correctly.
// ResultID stays the raw, machine-lookup id for display.
func (r *Result) DedupID() string {
	switch r.Type {
	case TypeCheckpoint:
		if r.Checkpoint != nil && r.Checkpoint.ID != "" {
			return repoQualifiedKey(r.Checkpoint.Org, r.Checkpoint.Repo, r.Checkpoint.ID)
		}
	case TypeCommit:
		if r.Commit != nil && r.Commit.CommitSHA != "" {
			return repoQualifiedKey(r.Commit.Org, r.Commit.Repo, r.Commit.CommitSHA)
		}
	case TypeSession:
		if r.Session != nil && r.Session.SessionID == "" && r.Session.MatchedCheckpointID != "" {
			return repoQualifiedKey(r.Session.Org, r.Session.Repo, r.Session.MatchedCheckpointID)
		}
	}
	return r.ResultID()
}

// repoQualifiedKey namespaces a repo-scoped (or repo-shared) id by its repo.
// org/repo are lowercased because the same repo can reach different cells under
// different casing (git remote entireio/CLI vs repo index entireio/cli — see
// resolveRepoFilters), and a casing skew would otherwise leak a duplicate.
func repoQualifiedKey(org, repo, id string) string {
	return strings.ToLower(org) + "\x00" + strings.ToLower(repo) + "\x00" + id
}

// ResultTitle returns the primary display text for any result type. Repo/PR
// raw payloads identify themselves via "title", "name", or "fullName".
func (r *Result) ResultTitle() string {
	if v := resultField(r,
		func(c *CheckpointResult) string {
			// Prefer the commit title over the prompt; fall back to the prompt
			// for uncommitted checkpoints. The full prompt remains in the detail view.
			if c.CommitSubject != nil && *c.CommitSubject != "" {
				return *c.CommitSubject
			}
			if c.CommitMessage != nil && *c.CommitMessage != "" {
				return *c.CommitMessage
			}
			return c.Prompt
		},
		func(c *CommitResult) string {
			if c.CommitSubject != "" {
				return c.CommitSubject
			}
			return c.CommitMessage
		},
		func(s *SessionResult) string { return s.DisplayName }); v != "" {
		return v
	}
	return r.rawString("title", "name", "fullName")
}

// ResultDescription returns the repo description for raw-payload rows
// (searcher.RepoResult). Typed rows return "" — rawFields is never populated
// for them.
func (r *Result) ResultDescription() string {
	return r.rawString("description")
}

// ResultCheckpointCount returns the indexed checkpoint count for raw-payload
// repo rows (searcher.RepoResult), 0 elsewhere.
func (r *Result) ResultCheckpointCount() int {
	var n int
	if err := json.Unmarshal(r.rawFields["checkpointCount"], &n); err != nil {
		return 0
	}
	return n
}

// TypeCounts holds per-type result counts.
type TypeCounts struct {
	Repos       int `json:"repos"`
	Checkpoints int `json:"checkpoints"`
	Commits     int `json:"commits"`
	PRs         int `json:"prs"`
	Sessions    int `json:"sessions"`
}

// Timing holds search performance timing data.
type Timing struct {
	TotalMs            *float64 `json:"total_ms"`
	KeywordMs          *float64 `json:"keyword_ms"`
	EmbeddingMs        *float64 `json:"embedding_ms"`
	VectorMs           *float64 `json:"vector_ms"`
	RerankMs           *float64 `json:"rerank_ms"`
	FanoutMs           *float64 `json:"fanout_ms"`
	SessionHydrationMs *float64 `json:"session_hydration_ms"`
}

// Response is the search service response.
type Response struct {
	Results  []Result    `json:"results"`
	Total    int         `json:"total"`
	Page     int         `json:"page"`
	Error    string      `json:"error,omitempty"`
	Timing   *Timing     `json:"timing,omitempty"`
	Reranked *bool       `json:"reranked,omitempty"`
	Counts   *TypeCounts `json:"counts,omitempty"`

	// Completeness metadata, same names and semantics as the BFF's merged
	// response (entire.io api/src/routes/search.ts mergeCellResponses) so web
	// and CLI surface identical signals (ENT-1777). Parsed from each cell and
	// re-synthesized by the CLI's own merge.
	Partial            bool            `json:"partial,omitempty"`
	Truncated          bool            `json:"truncated,omitempty"`
	CoverageIncomplete bool            `json:"coverage_incomplete,omitempty"`
	TruncatedTypes     map[string]bool `json:"truncated_types,omitempty"`
	CountsLowerBound   map[string]bool `json:"counts_lower_bound,omitempty"`

	// Warnings are client-side completeness notes (e.g. a truncated repo
	// index or a failed region in a cross-cell fan-out) surfaced to the user
	// on stderr. Never part of the wire format.
	Warnings []string `json:"-"`
}

// Config holds the configuration for a search request.
type Config struct {
	Owner    string
	Repo     string
	Repos    []string
	AllRepos bool // When true, search all accessible repos (no repo scoping)
	Query    string
	Limit    int
	Author   string // Filter by author name
	Date     string // Filter by time period: "week" or "month"
	Branch   string // Filter by branch name
	Page     int    // 1-based page number (0 means omit, API defaults to 1)
}

// ScopeSlugs resolves the repo scope of a search: the explicit repo filters
// (an explicit owner/name filter always scopes the search, even when
// --all-repos is also set — the more specific filter wins), else allRepos for
// an unfiltered repo:* / --all-repos search, else the current-repo default.
// slugs empty with allRepos false means no scope could be determined.
func (c Config) ScopeSlugs() (slugs []string, allRepos bool) {
	for _, repo := range c.Repos {
		if repo != AllReposFilter {
			slugs = append(slugs, repo)
		}
	}
	if len(slugs) > 0 {
		return slugs, false
	}
	if c.AllRepos || (len(c.Repos) == 1 && c.Repos[0] == AllReposFilter) {
		return nil, true
	}
	if c.Owner != "" && c.Repo != "" {
		return []string{c.Owner + "/" + c.Repo}, false
	}
	return nil, false
}

// HasFilters reports whether any filter fields are set on the config.
func (c Config) HasFilters() bool {
	return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0 || c.AllRepos
}

// ParsedInput holds the parsed query and optional filters extracted from search input.
type ParsedInput struct {
	Query  string
	Author string
	Date   string
	Branch string
	Repos  []string
}

// ParseSearchInput extracts filter prefixes from raw input.
// Supports quoted values for single-value filters, for example: author:"alice smith".
// Remaining tokens become the query.
func ParseSearchInput(raw string) ParsedInput {
	var p ParsedInput
	var queryParts []string

	tokens := tokenizeInput(raw)
	for _, tok := range tokens {
		switch {
		case strings.HasPrefix(tok, "author:"):
			p.Author = strings.Trim(tok[len("author:"):], "\"")
		case strings.HasPrefix(tok, "date:"):
			p.Date = strings.Trim(tok[len("date:"):], "\"")
		case strings.HasPrefix(tok, "branch:"):
			p.Branch = strings.Trim(tok[len("branch:"):], "\"")
		case strings.HasPrefix(tok, "repo:"):
			p.Repos = AppendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
		default:
			queryParts = append(queryParts, tok)
		}
	}

	p.Query = strings.Join(queryParts, " ")
	return p
}

// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
func tokenizeInput(s string) []string {
	var tokens []string
	i := 0
	s = strings.TrimSpace(s)
	for i < len(s) {
		// Skip whitespace
		for i < len(s) && s[i] == ' ' {
			i++
		}
		if i >= len(s) {
			break
		}

		start := i

		// Look ahead: is this a prefix:"quoted" token?
		if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
			// Found prefix:" — scan to closing quote
			quoteStart := i + colonIdx + 2
			endQuote := strings.IndexByte(s[quoteStart:], '"')
			if endQuote >= 0 {
				i = quoteStart + endQuote + 1
				tokens = append(tokens, s[start:i])
				continue
			}
		}

		// Regular token: advance to next space
		for i < len(s) && s[i] != ' ' {
			i++
		}
		tokens = append(tokens, s[start:i])
	}
	return tokens
}

func parseListFilter(raw string) []string {
	if raw == "" {
		return nil
	}

	parts := strings.Split(raw, ",")
	values := make([]string, 0, len(parts))
	for _, part := range parts {
		value := strings.Trim(strings.TrimSpace(part), "\"")
		if value == "" {
			continue
		}
		values = append(values, value)
	}

	return values
}

// ValidateRepoFilters ensures each repo filter matches backend semantics.
// Multiple explicit repo filters are accepted: the v4 query-serve path resolves
// each and fans out across the cells hosting them, mirroring code search.
func ValidateRepoFilters(repos []string) error {
	for _, repo := range repos {
		if !isValidRepoFilter(repo) {
			return fmt.Errorf(
				"invalid repo filter %q: expected owner/name, gh/owner/repo, a repo ULID, or *; if you meant all repos, quote the asterisk: --repo '*'",
				repo,
			)
		}
	}
	return nil
}

// isValidRepoFilter reports whether repo is a filter shape the search backends
// can resolve. It accepts every form the CLI help advertises and that the
// resolvers handle downstream — a bare owner/name slug, a prefixed path
// (gh/owner/repo, et/proj/repo, git/owner/repo), a raw repo ULID, or the
// all-repos wildcard — so validation never rejects a filter the semantic v4
// lookup (lookupFilter) or code-search resolver (resolveRepoFilters) would
// otherwise resolve. It still rejects obvious mistakes like a bare filename.
func isValidRepoFilter(repo string) bool {
	if repo == AllReposFilter {
		return true
	}
	if repo == "" || strings.Contains(repo, " ") {
		return false
	}
	// Raw repo ULID: the v4 route keys on ULIDs and lookupFilter matches a
	// prefix-less token against repo IDs.
	if _, err := ulid.Parse(repo); err == nil {
		return true
	}
	// A slug or prefixed path: owner/name or <prefix>/owner/repo. Every
	// path segment must be non-empty.
	parts := strings.Split(repo, "/")
	if len(parts) < 2 || len(parts) > 3 {
		return false
	}
	for _, part := range parts {
		if part == "" {
			return false
		}
	}
	return true
}

// AppendUnique appends values to existing, skipping any already present, and
// returns the result. Order is preserved (first occurrence wins).
func AppendUnique(existing []string, values ...string) []string {
	if len(values) == 0 {
		return existing
	}

	seen := make(map[string]struct{}, len(existing)+len(values))
	for _, value := range existing {
		seen[value] = struct{}{}
	}
	for _, value := range values {
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		existing = append(existing, value)
	}

	return existing
}

// CellV4 performs a v4 query-serve search against a single entire-api
// cell, via the pre-authenticated client (bearer = jurisdictional identity
// token; host = the cell). repoIDs are repo ULIDs to scope to (the v4 route is
// per-repo and keys on ULIDs, not owner/name slugs); an empty repoIDs means
// "every repo the caller can access in this cell" — query-serve fans out across
// those namespaces itself. The cross-cell fan-out and merge live in the cli
// layer (mirroring code search), so this is the single-cell primitive it calls.
func CellV4(ctx context.Context, client *api.Client, cfg Config, repoIDs []string) (*Response, error) {
	ctx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()

	q := url.Values{}
	q.Set("q", cfg.Query)
	filtered := false
	for _, id := range repoIDs {
		if id != "" {
			q.Add("repo", id)
			filtered = true
		}
	}
	addCommonSearchParams(q, cfg)

	resp, err := client.Get(ctx, v4ServicePath+"?"+q.Encode())
	if err != nil {
		return nil, fmt.Errorf("calling search service: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("reading response: %w", err)
	}
	if resp.StatusCode == http.StatusNotFound {
		// Two distinct 404s share this status. A JSON error body is
		// query-serve answering through the gateway: the route exists but the
		// repo filter matched nothing the caller may search (not indexed, or
		// the owner org isn't flag-enabled — entire-search fails closed,
		// existence not disclosed). A plain "404 page not found" is the
		// gateway itself: no semantic-search route, query-serve not deployed
		// in this cell. Deployed cells answer unfiltered searches of unknown
		// repos with an empty 200, so the split is unambiguous. The
		// repo-filter-miss reading only holds when a filter was actually sent
		// — an unfiltered call named no repo to blame, so its JSON 404
		// (whatever produced it) degrades to the ErrCellUnavailable fail-safe.
		var errResp struct {
			Error string `json:"error"`
		}
		if filtered && json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			// Wrap rather than return the bare sentinel so the server's own
			// message survives into debug logs; errors.Is still matches.
			return nil, fmt.Errorf("%w: %s", ErrRepoFilterUnmatched, errResp.Error)
		}
		return nil, ErrCellUnavailable
	}
	return parseSearchResponse(resp.StatusCode, body)
}

// addCommonSearchParams sets the query params other than the repo scoping
// (repo IDs are added by CellV4's caller). types is deliberately never sent —
// the backend returns all types.
func addCommonSearchParams(q url.Values, cfg Config) {
	if cfg.Limit > 0 {
		q.Set("limit", strconv.Itoa(cfg.Limit))
	}
	if cfg.Author != "" {
		q.Set("author", cfg.Author)
	}
	if cfg.Date != "" {
		q.Set("date", cfg.Date)
	}
	if cfg.Branch != "" {
		q.Set("branch", cfg.Branch)
	}
	if cfg.Page > 0 {
		q.Set("page", strconv.Itoa(cfg.Page))
	}
}

// parseSearchResponse decodes a search response body, preserving the
// long-standing error wording so callers (and error-message assertions) are
// unchanged.
func parseSearchResponse(statusCode int, body []byte) (*Response, error) {
	if statusCode != http.StatusOK {
		var errResp struct {
			Error string `json:"error"`
		}
		if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
			return nil, fmt.Errorf("search service error (%d): %s", statusCode, errResp.Error)
		}
		return nil, fmt.Errorf("search service returned %d: %s", statusCode, string(body))
	}

	var result Response
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
	}

	if result.Error != "" {
		return nil, fmt.Errorf("search service error: %s", result.Error)
	}

	return &result, nil
}

// Package search provides search functionality via the Entire search service.
package search

import (
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/gitremote"
)

// ParseGitHubRemote extracts owner and repo from a git remote URL that resolves
// to GitHub. It accepts direct GitHub remotes (SCP-style SSH, ssh://, and
// https://) as well as Entire mirror remotes (entire://host/gh/owner/repo),
// whose forge prefix maps back to github.com. Remotes resolving to any other
// host, or whose path holds extra segments beyond owner/repo, are rejected.
func ParseGitHubRemote(remoteURL string) (owner, repo string, err error) {
	remoteURL = strings.TrimSpace(remoteURL)
	if remoteURL == "" {
		return "", "", errors.New("empty remote URL")
	}
	info, err := gitremote.ParseURL(remoteURL)
	if err != nil {
		return "", "", fmt.Errorf("parsing remote URL: %w", err)
	}
	if host := info.CanonicalHost(); host != "github.com" {
		return "", "", fmt.Errorf("remote is not a GitHub repository (host: %s)", host)
	}
	if strings.Contains(info.Repo, "/") {
		return "", "", fmt.Errorf("remote path has extra segments beyond owner/repo: %s", gitremote.RedactURL(remoteURL))
	}
	return info.Owner, info.Repo, nil
}

